const hex=(n,w)=>n.toString(16).toUpperCase().padStart(w,'0');
class Chip8{
 constructor(){this.reset();}
 reset(){this.mem=new Uint8Array(4096);this.mem.set(FONT,0x50);this.V=new Uint8Array(16);this.I=0;this.pc=0x200;
  this.stack=[];this.dt=0;this.st=0;this.fb=new Uint8Array(64*32);this.keys=new Array(16).fill(false);this.dirty=true;}
 load(rom){this.reset();this.mem.set(rom.slice(0,4096-0x200),0x200);}
 step(){
  const m=this.mem,V=this.V,pc=this.pc;
  const op=(m[pc]<<8)|m[(pc+1)&4095];this.pc=(pc+2)&4095;
  const x=(op>>8)&15,y=(op>>4)&15,n=op&15,nn=op&255,nnn=op&0xFFF;
  switch(op>>12){
  case 0:if(op==0x00E0){this.fb.fill(0);this.dirty=true;}
   else if(op==0x00EE){if(this.stack.length)this.pc=this.stack.pop();}break;
  case 1:this.pc=nnn;break;
  case 2:if(this.stack.length<16)this.stack.push(this.pc);this.pc=nnn;break;
  case 3:if(V[x]==nn)this.pc+=2;break;
  case 4:if(V[x]!=nn)this.pc+=2;break;
  case 5:if(V[x]==V[y])this.pc+=2;break;
  case 6:V[x]=nn;break;
  case 7:V[x]+=nn;break;
