   switch(n){
   case 0:V[x]=b;break;case 1:V[x]=a|b;break;case 2:V[x]=a&b;break;case 3:V[x]=a^b;break;
   case 4:{const s=a+b;V[x]=s;V[15]=s>255?1:0;break;}
   case 5:V[x]=a-b;V[15]=a>=b?1:0;break;
   case 6:V[x]=a>>1;V[15]=a&1;break;
   case 7:V[x]=b-a;V[15]=b>=a?1:0;break;
   case 0xE:V[x]=a<<1;V[15]=a>>7;break;}
   break;}
  case 9:if(V[x]!=V[y])this.pc+=2;break;
  case 0xA:this.I=nnn;break;
  case 0xB:this.pc=(nnn+V[0])&0xFFF;break;
  case 0xC:V[x]=(Math.random()*256)&nn;break;
  case 0xD:{const px=V[x]%64,py=V[y]%32;V[15]=0;
   for(let r=0;r<n;r++){const yy=py+r;if(yy>=32)break;const b=m[(this.I+r)&4095];
    for(let c=0;c<8;c++){const xx=px+c;if(xx>=64)break;
     if(b&(0x80>>c)){const k=yy*64+xx;if(this.fb[k])V[15]=1;this.fb[k]^=1;}}}
   this.dirty=true;break;}
  case 0xE:if(nn==0x9E){if(this.keys[V[x]&15])this.pc+=2;}else if(nn==0xA1){if(!this.keys[V[x]&15])this.pc+=2;}break;
  case 0xF:switch(nn){
   case 0x07:V[x]=this.dt;break;
   case 0x0A:{const k=this.keys.indexOf(true);if(k>=0)V[x]=k;else this.pc=pc;break;}
   case 0x15:this.dt=V[x];break;
   case 0x18:this.st=V[x];break;
   case 0x1E:this.I=(this.I+V[x])&0xFFFF;break;
   case 0x29:this.I=0x50+(V[x]&15)*5;break;
   case 0x33:m[this.I&4095]=Math.floor(V[x]/100);m[(this.I+1)&4095]=Math.floor(V[x]/10)%10;m[(this.I+2)&4095]=V[x]%10;break;
   case 0x55:for(let i=0;i<=x;i++)m[(this.I+i)&4095]=V[i];this.I+=x+1;break;
   case 0x65:for(let i=0;i<=x;i++)V[i]=m[(this.I+i)&4095];this.I+=x+1;break;}
   break;}
  this.pc&=4095;
 }
 tick(){if(this.dt>0)this.dt--;if(this.st>0)this.st--;}
 static dis(op){
  const x='V'+hex((op>>8)&15,1),y='V'+hex((op>>4)&15,1),n=op&15,nn=hex(op&255,2),nnn=hex(op&0xFFF,3);
  switch(op>>12){
  case 0:return op==0xE0?'CLS':op==0xEE?'RET':'SYS '+nnn;
  case 1:return'JP '+nnn;case 2:return'CALL '+nnn;
  case 3:return`SE ${x}, ${nn}`;case 4:return`SNE ${x}, ${nn}`;case 5:return`SE ${x}, ${y}`;
  case 6:return`LD ${x}, ${nn}`;case 7:return`ADD ${x}, ${nn}`;
  case 8:return({0:'LD',1:'OR',2:'AND',3:'XOR',4:'ADD',5:'SUB',6:'SHR',7:'SUBN',0xE:'SHL'}[n]||'???')+` ${x}, ${y}`;
  case 9:return`SNE ${x}, ${y}`;case 0xA:return'LD I, '+nnn;case 0xB:return'JP V0, '+nnn;
  case 0xC:return`RND ${x}, ${nn}`;case 0xD:return`DRW ${x}, ${y}, ${n}`;
  case 0xE:return(op&255)==0x9E?`SKP ${x}`:(op&255)==0xA1?`SKNP ${x}`:'???';
  case 0xF:return({7:`LD ${x}, DT`,0xA:`LD ${x}, K`,0x15:`LD DT, ${x}`,0x18:`LD ST, ${x}`,0x1E:`ADD I, ${x}`,
   0x29:`LD F, ${x}`,0x33:`LD B, ${x}`,0x55:`LD [I], ${x}`,0x65:`LD ${x}, [I]`}[op&255]||'???');}
  return'???';}
}
